    "answer": "错误。马克思主义是在无产阶级革命实践中产生并发展起来的，是无产阶级根本利益的科学表现。鲜明的阶级性和实践性是马克思主义的根本特性。马克思说过：“哲学把无产阶级当作自己的物质武器，同样，无产阶级也把哲学当作自己的精神武器。”"
