    "answer": "答:\n（1）建设中国特色社会主义是中华民族走向共产主义的必由之路。一方面，要牢固树立和坚定共产主义的理想信念，正确把握历史发展规律，正确认识实现共产主义必然性；另一方面，立足中国国情，坚持“两个一百年”奋斗目标不动摇，构建经济、政治、文化、生态与社会五位一体协调发展的社会主义文明，逐步实现全体人民共同富裕。\n（2）积极投身中国特色社会主义事业，实现中华民族伟大复兴。共产主义理想是人类最伟大的社会理想，也是中国共产党的远大理想和最高纲领。中国特色社会主义共同理想，是共产主义远大理想在我国社会主义初级阶段的现实体现。坚持和发展中国特色社会主义，实现中华民族伟大复兴的中国梦，是全国各族人民的共同理想。我们要把追求个人理想与追求共同理想结合起来，把追求共同理想与追求远大理想结合起来，投身中国特色社会主义事业的伟大实践。"
