    "answer": "错误。第二次世界大战后，发达国家垄断资本主义的持续发展有力地促进了经济增长，但国家垄断资本主义没有根本改变垄断资本主义的性质。国家垄断资本主义在本质上是资产阶级国家力量同垄断组织力量结合在一起的垄断资本主义，它在促进生产力发展的同时，也强化了对劳动人民的掠夺，使垄断资产阶级的利益得到了更好的维护，从根本上起到了促进并维护资本主义制度发展的作用。国家垄断资本主义并没有从根本上消除资本主义的基本矛盾，其各种具体形式本质上都是私人垄断资本利用国家机器来为其发展服务的手段，是资产阶级国家代表资产阶级总利益、凌驾于个别垄断资本之上对社会经济进行调节的一种形式。"
